/** One native bot shell for chat, terminals, files, model settings and connectors. */
public class BotsActivity extends Activity {
    private final Handler main=new Handler(Looper.getMainLooper());private final ExecutorService io=Executors.newFixedThreadPool(3),inputs=Executors.newSingleThreadExecutor();
    private AgentApi api;private JSONObject state=new JSONObject(),detail;private String selected="",screen="Chat",draft="",signature="";
    private LinearLayout page,body,thread;private FrameLayout root,drawer;private EditText composer;private ScrollView chatScroll;private boolean visible,polling,follow=true;
    private BotWorkspace workspace;private ChatMarkdown markdown;private final Runnable poll=()->refresh(false);
    interface Result {void done(Object value)throws Exception;}
    int dp(int n){return AgentStyle.dp(this,n);}
    JSONObject json(Object...pairs){JSONObject value=new JSONObject();try{for(int i=0;i<pairs.length;i+=2)value.put((String)pairs[i],pairs[i+1]);}catch(Exception e){throw new IllegalArgumentException(e);}return value;}
    JSONObject currentState(){return state;}
    LinearLayout column(){LinearLayout v=new LinearLayout(this);v.setOrientation(LinearLayout.VERTICAL);return v;}
    LinearLayout row(){LinearLayout v=new LinearLayout(this);v.setGravity(Gravity.CENTER_VERTICAL);return v;}
    TextView text(String value,int size){TextView v=AgentStyle.text(this,value,size);v.setPadding(dp(8),dp(6),dp(8),dp(6));return v;}
    TextView muted(String value,int size){TextView v=text(value,size);v.setTextColor(AgentStyle.MUTED);return v;}
    Button button(LinearLayout parent,String title,Runnable action,boolean primary){Button v=new Button(this);v.setText(title);AgentStyle.button(v,primary);parent.addView(v);v.setOnClickListener(w->action.run());return v;}
    EditText field(LinearLayout parent,String label,String value,boolean secret){parent.addView(text(label,12));EditText v=new EditText(this);AgentStyle.input(v);v.setSingleLine(true);if(secret)v.setInputType(129);v.setText(value);parent.addView(v);return v;}
    void request(String method,String path,JSONObject data,Result done){requestQuiet(method,path,data,done,()->{} ,true);}
    void requestQuiet(String method,String path,JSONObject data,Result done,Runnable failed){requestQuiet(method,path,data,done,failed,false);}
    private void requestQuiet(String method,String path,JSONObject data,Result done,Runnable failed,boolean showError){if(api==null)return;AgentApi connection=api;io.execute(()->{try{Object value=connection.request(method,path,data);main.post(()->{if(!isDestroyed())try{done.done(value);}catch(Exception e){error(e);}});}catch(Exception e){main.post(()->{if(!isDestroyed()){failed.run();if(showError)error(e);}});}});}
    void terminalInput(String id,JSONObject data){AgentApi connection=api;if(connection==null)return;inputs.execute(()->{try{connection.request("POST","/terminals/"+id+"/input",data);}catch(Exception e){main.post(()->{if(!isDestroyed())error(e);});}});}
    void error(Exception e){new AlertDialog.Builder(this).setTitle("Pocket Agent").setMessage(e.getMessage()).setPositiveButton("OK",null).show();}
    void openUrl(String url){try{Uri parsed=Uri.parse(url);if(!Arrays.asList("http","https").contains(parsed.getScheme()))throw new IllegalArgumentException("Use an HTTP or HTTPS link");startActivity(new Intent(Intent.ACTION_VIEW,parsed));}catch(Exception e){error(e);}}
    @Override public void onCreate(Bundle saved){super.onCreate(saved);workspace=new BotWorkspace(this);markdown=new ChatMarkdown(this);selected=getIntent().getStringExtra("botId");if(selected==null||!selected.matches("[0-9a-f-]{36}"))selected="";if(saved!=null){selected=saved.getString("bot",selected);screen=saved.getString("screen","Chat");}if(!getSharedPreferences("bot-setup",0).getBoolean("seen-v2",false))screen="Setup";LinearLayout loading=column();loading.setBackgroundColor(AgentStyle.BACK);loading.setPadding(dp(24),dp(48),dp(24),dp(24));loading.addView(text("Pocket Agent",24));loading.addView(muted("Starting your local bots...",14));setContentView(loading);}
    @Override protected void onSaveInstanceState(Bundle out){out.putString("bot",selected);out.putString("screen",screen);super.onSaveInstanceState(out);}
    @Override protected void onNewIntent(Intent intent){super.onNewIntent(intent);setIntent(intent);String id=intent.getStringExtra("botId");if(id!=null&&id.matches("[0-9a-f-]{36}")){if(api==null)selected=id;else open(id);}}
    @Override protected void onResume(){super.onResume();visible=true;getSharedPreferences("bot-runtime",0).edit().putBoolean("enabled",true).apply();startForegroundService(new Intent(this,RuntimeService.class).putExtra("botsEnabled",true));connect();}
    private void connect(){if(!visible)return;if(!RuntimeService.ready){LinearLayout wait=column();wait.setPadding(dp(24),dp(48),dp(24),dp(24));wait.setBackgroundColor(AgentStyle.BACK);wait.addView(text("Pocket Agent",24));wait.addView(muted(RuntimeService.status,14));button(wait,"Retry setup",()->startForegroundService(new Intent(this,RuntimeService.class)),false);button(wait,"View runtime log",()->{try{new AlertDialog.Builder(this).setTitle("Runtime log").setMessage(Io.text(new File(getFilesDir(),"runtime.log"))).setPositiveButton("Close",null).show();}catch(Exception e){error(e);}},false);setContentView(wait);main.postDelayed(this::connect,1000);return;}try{api=new AgentApi((String)new JSONTokener(Io.text(new File(getFilesDir(),"state/token.json"))).nextValue());refresh(true);}catch(Exception e){error(e);}}
    @Override protected void onPause(){saveDraft();visible=false;main.removeCallbacks(poll);workspace.stop();super.onPause();}
    @Override protected void onDestroy(){main.removeCallbacksAndMessages(null);workspace.stop();io.shutdownNow();inputs.shutdownNow();super.onDestroy();}
    private void saveDraft(){if(composer!=null)getSharedPreferences("bot-chats",0).edit().putString("draft-"+selected,composer.getText().toString()).apply();}
    private void refresh(boolean rebuild){if(!visible||api==null)return;if(polling){main.postDelayed(()->refresh(rebuild),100);return;}polling=true;String id=selected;io.execute(()->{try{JSONObject next=api.get("/state"),nextDetail=id.isEmpty()?null:api.get("/bots/"+id);main.post(()->{polling=false;if(!visible||!id.equals(selected))return;state=next;detail=nextDetail;if(!next.optBoolean("botEngineEnabled"))request("PUT","/bots/engine",json("enabled",true),v->{});String changed=(id.isEmpty()?next.optJSONArray("bots"):nextDetail).toString();if(rebuild||body==null){shell();signature="";}if(!signature.equals(changed)){signature=changed;if(screen.equals("Chat")){if(selected.isEmpty())inbox();else renderThread();}}main.postDelayed(poll,1000);});}catch(Exception e){main.post(()->{polling=false;if(visible){main.postDelayed(poll,2000);if(rebuild)error(e);}});}});}
    private void open(String id){saveDraft();selected=id;screen="Chat";draft=getSharedPreferences("bot-chats",0).getString("draft-"+id,"");detail=null;signature="";composer=null;workspace.stop();main.removeCallbacks(poll);refresh(true);}
    void showSetup(){showScreen("Setup");}
    private void showScreen(String next){if(page!=null){getSystemService(android.view.inputmethod.InputMethodManager.class).hideSoftInputFromWindow(page.getWindowToken(),0);page.clearFocus();}saveDraft();screen=next;signature="";shell();if(screen.equals("Chat")){if(selected.isEmpty())inbox();else renderThread();}}
    private void shell(){
        workspace.stop();page=column();page.setBackgroundColor(AgentStyle.BACK);page.setPadding(dp(12),dp(8),dp(12),dp(8));page.setOnApplyWindowInsetsListener((v,insets)->{v.setPadding(dp(12)+insets.getSystemWindowInsetLeft(),dp(8)+insets.getSystemWindowInsetTop(),dp(12)+insets.getSystemWindowInsetRight(),dp(8)+insets.getSystemWindowInsetBottom());return insets.consumeSystemWindowInsets();});LinearLayout header=row();header.addView(new AgentIcon(this,"menu","Open sidebar",this::menu),new LinearLayout.LayoutParams(dp(44),dp(44)));LinearLayout identity=column();String title=screen.equals("Chat")?(selected.isEmpty()?"Pocket Agent":detail.optJSONObject("bot").optString("name")):screen.equals("Setup")?"Setup & permissions":screen.equals("Servers")?"Servers & sharing":screen.equals("Terminal")&&selected.isEmpty()?"Main terminal":screen.equals("Settings")?"Settings":detail==null?screen:detail.optJSONObject("bot").optString("name");TextView name=text(title,20);name.setTypeface(AgentStyle.font(this),Typeface.BOLD);identity.addView(name);identity.addView(muted(selected.isEmpty()?"Your local bots":"Code, browse and use your phone",11));header.addView(identity,new LinearLayout.LayoutParams(0,-2,1));header.addView(new AgentIcon(this,selected.isEmpty()?"plus":"settings",selected.isEmpty()?"Create bot":"Bot settings",()->editBot(selected.isEmpty()?null:detail.optJSONObject("bot"))),new LinearLayout.LayoutParams(dp(44),dp(44)));page.addView(header);
        if(!selected.isEmpty()&&Arrays.asList("Chat","Terminal","Files").contains(screen)){LinearLayout tabs=AgentStyle.segment(this);for(String tab:new String[]{"Chat","Terminal","Files"}){Button choice=button(tabs,tab,()->showScreen(tab),false);choice.setLayoutParams(new LinearLayout.LayoutParams(0,dp(40),1));AgentStyle.selected(choice,screen.equals(tab));}page.addView(tabs,new LinearLayout.LayoutParams(-1,dp(48)));}
        body=column();page.addView(body,new LinearLayout.LayoutParams(-1,0,1));composer=null;thread=null;root=new FrameLayout(this);root.addView(page);drawer=null;setContentView(root);
        if(screen.equals("Setup")){setup();return;}if(!screen.equals("Chat")){workspace.show(body,screen,selected.isEmpty()?"":detail.optJSONObject("bot").optString("projectId"));return;}
        if(selected.isEmpty()){inbox();return;}
        chatScroll=new ScrollView(this);thread=column();chatScroll.addView(thread);body.addView(chatScroll,new LinearLayout.LayoutParams(-1,0,1));chatScroll.setOnScrollChangeListener((v,x,y,ox,oy)->follow=y+chatScroll.getHeight()>=thread.getHeight()-dp(60));LinearLayout input=row();input.setPadding(dp(4),dp(4),dp(4),dp(4));input.setBackground(AgentStyle.surface(this,AgentStyle.PANEL,28,true));composer=new EditText(this);AgentStyle.input(composer);composer.setBackgroundColor(android.graphics.Color.TRANSPARENT);composer.setHint("Message "+detail.optJSONObject("bot").optString("name")+"...");composer.setMaxLines(5);composer.setText(getSharedPreferences("bot-chats",0).getString("draft-"+selected,draft));input.addView(composer,new LinearLayout.LayoutParams(0,-2,1));AgentIcon send=new AgentIcon(this,"send","Send to bot",this::send);send.setBackground(AgentStyle.surface(this,AgentStyle.BLUE,28,false));input.addView(send,new LinearLayout.LayoutParams(dp(44),dp(44)));page.addView(input);
    }
    private void menu(){if(drawer!=null){root.removeView(drawer);drawer=null;return;}drawer=new FrameLayout(this);drawer.setBackgroundColor(0xaa000000);root.addView(drawer,new FrameLayout.LayoutParams(-1,-1));drawer.setOnClickListener(v->{root.removeView(drawer);drawer=null;});LinearLayout panel=column();panel.setClickable(true);panel.setBackgroundColor(AgentStyle.BACK);panel.setPadding(dp(12),dp(32),dp(12),dp(24));drawer.addView(panel,new FrameLayout.LayoutParams(Math.min(dp(300),getResources().getDisplayMetrics().widthPixels-dp(40)),-1));panel.addView(text("Pocket Agent",24));button(panel,"All bots",()->open(""),false);button(panel,"Create bot",()->{menu();editBot(null);},false);ScrollView recent=new ScrollView(this);LinearLayout list=column();recent.addView(list);panel.addView(recent,new LinearLayout.LayoutParams(-1,0,1));JSONArray bots=state.optJSONArray("bots");if(bots!=null)for(int i=0;i<bots.length();i++){JSONObject bot=bots.optJSONObject(i);button(list,bot.optString("name"),()->open(bot.optString("id")),false);}button(panel,"Main terminal",()->{saveDraft();composer=null;selected="";detail=null;showScreen("Terminal");},false);button(panel,"Servers & sharing",()->showScreen("Servers"),false);button(panel,"MCP connections",()->{menu();connections();},false);if(!selected.isEmpty())button(panel,"Select MCP tools for this bot",()->{menu();selectConnections();},false);button(panel,"Settings",()->showScreen("Settings"),false);button(panel,"Setup & permissions",this::showSetup,false);}
    private void inbox(){body.removeAllViews();ScrollView scroll=new ScrollView(this);LinearLayout list=column();scroll.addView(list);body.addView(scroll,new LinearLayout.LayoutParams(-1,0,1));JSONArray bots=state.optJSONArray("bots");if(bots==null||bots.length()==0){list.addView(text("Meet your local bots",23));list.addView(muted("Give a bot a name and instructions. Every bot can code, browse and use your phone.",14));button(list,"Create my first bot",()->editBot(null),true);return;}for(int i=0;i<bots.length();i++){JSONObject bot=bots.optJSONObject(i);LinearLayout item=row();item.setPadding(dp(6),dp(16),dp(6),dp(16));TextView avatar=text(bot.optString("name","?").substring(0,1).toUpperCase(Locale.ROOT),20);avatar.setGravity(Gravity.CENTER);avatar.setBackground(AgentStyle.surface(this,0xff233b70,24,false));item.addView(avatar,new LinearLayout.LayoutParams(dp(48),dp(48)));LinearLayout copy=column();LinearLayout title=row();TextView name=text(bot.optString("name"),16);name.setTypeface(AgentStyle.font(this),Typeface.BOLD);title.addView(name,new LinearLayout.LayoutParams(0,-2,1));title.addView(muted(bot.optJSONObject("active")!=null?"Working":bot.optBoolean("enabled")?"Ready":"Paused",10));copy.addView(title);JSONObject last=bot.optJSONObject("lastMessage");TextView preview=muted(last==null?bot.optString("role"):last.optString("text"),12);preview.setMaxLines(2);preview.setEllipsize(android.text.TextUtils.TruncateAt.END);copy.addView(preview);if(bot.optInt("queued")>0)copy.addView(muted(bot.optInt("queued")+" queued",10));item.addView(copy,new LinearLayout.LayoutParams(0,-2,1));list.addView(item);item.setOnClickListener(v->open(bot.optString("id")));View line=new View(this);line.setBackgroundColor(AgentStyle.BORDER);list.addView(line,new LinearLayout.LayoutParams(-1,dp(1)));}}
    private void send(){String value=composer.getText().toString().trim();if(value.isEmpty())return;if(!state.optJSONObject("settings").optBoolean("hasKey")){new AlertDialog.Builder(this).setTitle("Connect your model").setMessage("Save your BYOK connection before sending tasks. Your draft will be kept.").setPositiveButton("Open settings",(d,n)->showScreen("Settings")).setNegativeButton("Cancel",null).show();return;}String id=selected;request("POST","/bots/"+id+"/messages",json("text",value),v->{if(id.equals(selected)&&composer!=null)composer.setText("");draft="";getSharedPreferences("bot-chats",0).edit().remove("draft-"+id).apply();request("POST","/bots/"+id+"/resume",json(),r->refresh(false));});}
    private void bubble(String value,boolean user){LinearLayout align=column();align.setGravity(user?Gravity.RIGHT:Gravity.LEFT);TextView message=text(value,14);message.setTextIsSelectable(true);if(!user)markdown.set(message,value);message.setPadding(dp(14),dp(12),dp(14),dp(12));message.setMaxWidth(getResources().getDisplayMetrics().widthPixels-dp(64));message.setBackground(AgentStyle.surface(this,user?AgentStyle.BLUE:AgentStyle.PANEL,20,!user));align.addView(message,new LinearLayout.LayoutParams(-2,-2));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.setMargins(0,dp(7),0,dp(7));thread.addView(align,p);}
    private void renderThread(){if(thread==null||detail==null||!screen.equals("Chat"))return;int old=chatScroll.getScrollY();boolean scroll=follow;thread.removeAllViews();JSONObject bot=detail.optJSONObject("bot");JSONArray messages=detail.optJSONArray("messages");for(int i=0;i<messages.length();i++){JSONObject message=messages.optJSONObject(i);if(message.optString("role").equals("system"))thread.addView(muted(message.optString("text"),11));else bubble(message.optString("text"),message.optString("role").equals("user"));}JSONObject session=detail.optJSONObject("session");if(session!=null){JSONObject streaming=session.optJSONObject("streaming");if(streaming!=null){StringBuilder output=new StringBuilder();JSONArray parts=streaming.optJSONArray("content");if(parts!=null)for(int i=0;i<parts.length();i++)if(parts.optJSONObject(i).optString("type").equals("text"))output.append(parts.optJSONObject(i).optString("text"));if(output.length()>0)bubble(output.toString(),false);}JSONArray approvals=session.optJSONArray("approvals");if(approvals!=null)for(int i=0;i<approvals.length();i++){JSONObject approval=approvals.optJSONObject(i);thread.addView(text("Allow "+approval.optString("tool")+"?\n"+approval.opt("args"),12));LinearLayout actions=row();thread.addView(actions);for(boolean allow:new boolean[]{true,false})button(actions,allow?"Allow":"Deny",()->request("POST","/approvals/"+approval.optString("id"),json("allow",allow),v->refresh(false)),allow);}}
        JSONObject phone=detail.optJSONObject("mobileTask");if(phone!=null&&phone.optJSONObject("question")!=null){JSONObject question=phone.optJSONObject("question");bubble(question.optString("text"),false);EditText reply=new EditText(this);AgentStyle.input(reply);reply.setHint("Reply to your bot...");thread.addView(reply);button(thread,"Send reply",()->{String answer=reply.getText().toString().trim();if(answer.isEmpty())return;startForegroundService(new Intent(this,MobileOverlayService.class).putExtra("taskId",phone.optString("id")).putExtra("expand",true));main.postDelayed(()->request("POST","/mobile/tasks/"+phone.optString("id")+"/answer",json("questionId",question.optString("id"),"text",answer),v->refresh(false)),400);},true);}
        JSONArray jobs=detail.optJSONArray("jobs");boolean busy=false,paused=false;for(int i=Math.max(0,jobs.length()-8);i<jobs.length();i++){JSONObject job=jobs.optJSONObject(i);String status=job.optString("status");if(Arrays.asList("completed","cancelled","failed").contains(status))continue;busy|=Arrays.asList("running","arming","waiting").contains(status);paused|=status.equals("paused");LinearLayout card=column();AgentStyle.card(card);card.addView(muted(status.toUpperCase(Locale.ROOT)+" - "+job.optString("text"),11));if(!job.optString("error").isEmpty())card.addView(muted(job.optString("error"),12));if(job.optBoolean("phoneArming")){card.addView(muted("Waiting for phone access. Enable setup permissions and unlock your device.",12));button(card,"Open setup",this::showSetup,false);}button(card,"Cancel task",()->request("POST","/bots/"+selected+"/jobs/"+job.optString("id")+"/cancel",json(),v->refresh(false)),false);thread.addView(card);}
        if(busy){LinearLayout thinking=row();ThinkingOrbView orb=new ThinkingOrbView(this);orb.state("running");thinking.addView(orb,new LinearLayout.LayoutParams(dp(30),dp(30)));thinking.addView(muted("Working - you can queue another task",12));thread.addView(thinking);}
        if(busy||paused||!bot.optBoolean("enabled")){LinearLayout controls=row();thread.addView(controls);boolean resume=paused||!bot.optBoolean("enabled");button(controls,resume?"Resume bot":"Pause bot",()->request("POST","/bots/"+selected+(resume?"/resume":"/pause"),json(),v->refresh(false)),false);if(paused)button(controls,"Setup & permissions",this::showSetup,false);}
        if(bot.optInt("intervalMinutes")>0)button(thread,"Run routine now",()->request("POST","/bots/"+selected+"/routine/run",json(),v->refresh(false)),false);chatScroll.post(()->{if(scroll)chatScroll.fullScroll(View.FOCUS_DOWN);else chatScroll.scrollTo(0,old);});
    }
    private void editBot(JSONObject bot){boolean create=bot==null;LinearLayout form=column();form.setPadding(dp(16),dp(12),dp(16),dp(16));EditText name=field(form,"Name",create?"":bot.optString("name"),false),role=field(form,"Instructions",create?"":bot.optString("role"),false);role.setSingleLine(false);role.setMinLines(4);role.setGravity(Gravity.TOP);role.setHint("What should this bot help you with?");if(!create){button(form,"Tools, alerts & routines",()->botOptions(bot),false);button(form,"Select MCP connections",this::selectConnections,false);}AlertDialog dialog=new AlertDialog.Builder(this).setTitle(create?"Create a bot":"Bot profile").setView(form).setPositiveButton(create?"Create bot":"Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v->dialog.getButton(-1).setOnClickListener(w->request(create?"POST":"PUT",create?"/bots":"/bots/"+bot.optString("id"),json("name",name.getText().toString(),"role",role.getText().toString()),result->{dialog.dismiss();open(((JSONObject)result).optString("id"));})));dialog.show();}
    private void botOptions(JSONObject bot){LinearLayout form=column();form.setPadding(dp(16),dp(12),dp(16),dp(16));CheckBox shell=new CheckBox(this);shell.setText("Allow shell commands without asking");shell.setTextColor(AgentStyle.TEXT);shell.setChecked(bot.optBoolean("allowShell",true));form.addView(shell);CheckBox urgent=new CheckBox(this);urgent.setText("Allow ringing priority alerts");urgent.setTextColor(AgentStyle.TEXT);urgent.setChecked(bot.optBoolean("allowUrgent",true));form.addView(urgent);EditText interval=field(form,"Routine interval in minutes - 0 = off",bot.optString("intervalMinutes","0"),false),routine=field(form,"Routine task",bot.optString("heartbeat"),false);routine.setSingleLine(false);button(form,"Remove bot",()->new AlertDialog.Builder(this).setTitle("Remove this bot?").setMessage("Its workspace files will be kept.").setPositiveButton("Remove",(d,n)->request("DELETE","/bots/"+bot.optString("id"),null,v->open(""))).setNegativeButton("Cancel",null).show(),false);new AlertDialog.Builder(this).setTitle("Bot preferences").setView(form).setPositiveButton("Save",(d,n)->{try{request("PUT","/bots/"+bot.optString("id"),json("allowShell",shell.isChecked(),"allowUrgent",urgent.isChecked(),"dailyLimit",0,"intervalMinutes",Integer.parseInt(interval.getText().toString()),"heartbeat",routine.getText().toString()),v->refresh(false));}catch(Exception e){error(e);}}).setNegativeButton("Cancel",null).show();}
    private void selectConnections(){if(detail==null)return;JSONObject bot=detail.optJSONObject("bot");JSONArray all=state.optJSONArray("connectors"),current=bot.optJSONArray("connectors");LinearLayout form=column();Map<String,CheckBox> choices=new LinkedHashMap<>();if(all!=null)for(int i=0;i<all.length();i++){JSONObject connection=all.optJSONObject(i);CheckBox check=new CheckBox(this);check.setText(connection.optString("name"));check.setTextColor(AgentStyle.TEXT);check.setChecked(current!=null&&current.toString().contains(connection.optString("id")));form.addView(check);choices.put(connection.optString("id"),check);}button(form,"Manage MCP connections",this::connections,false);new AlertDialog.Builder(this).setTitle("Tools for "+bot.optString("name")).setView(form).setPositiveButton("Save",(d,n)->{JSONArray ids=new JSONArray();for(Map.Entry<String,CheckBox> entry:choices.entrySet())if(entry.getValue().isChecked())ids.put(entry.getKey());request("PUT","/bots/"+bot.optString("id"),json("connectors",ids),v->refresh(false));}).setNegativeButton("Cancel",null).show();}
    private boolean accessibility(){return com.artemis.helper.ArtemisAccessibilityService.getInstance()!=null;}
    private void setup(){body.removeAllViews();ScrollView scroll=new ScrollView(this);LinearLayout content=column();scroll.addView(content);body.addView(scroll,new LinearLayout.LayoutParams(-1,-1));content.addView(text("Set up your local bots",22));content.addView(muted("Every bot can code, browse and operate your phone. Shell commands and priority ringing are enabled by default; you can change them in each bot's preferences.",13));content.addView(text("Shell commands: allowed by default",14));content.addView(text("Priority ringing alerts: allowed by default",14));content.addView(muted("Alerts can ring while locked. Answer shows the message and uses an installed offline Android voice. Phone actions require an unlocked screen.",12));
        boolean notifications=getSystemService(NotificationManager.class).areNotificationsEnabled();button(content,(notifications?"Allowed: ":"Enable: ")+"Notifications & replies",()->{if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS)!=android.content.pm.PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{android.Manifest.permission.POST_NOTIFICATIONS},1);else startActivity(new Intent(Settings.ACTION_APP_NOTIFICATION_SETTINGS).putExtra(Settings.EXTRA_APP_PACKAGE,getPackageName()));},false);
        if(Build.VERSION.SDK_INT>=34)button(content,(getSystemService(NotificationManager.class).canUseFullScreenIntent()?"Allowed: ":"Enable: ")+"Full-screen alert permission",()->startActivity(new Intent(Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,Uri.parse("package:"+getPackageName()))),false);
        button(content,"Android voice data",()->{try{startActivity(new Intent(android.speech.tts.TextToSpeech.Engine.ACTION_INSTALL_TTS_DATA));}catch(ActivityNotFoundException e){Toast.makeText(this,"Install an offline voice in Android text-to-speech settings",Toast.LENGTH_LONG).show();}},false);
        button(content,(accessibility()?"Enabled: ":"Enable: ")+"Phone accessibility",()->startActivity(new Intent(Settings.ACTION_ACCESSIBILITY_SETTINGS)),false);button(content,(Settings.canDrawOverlays(this)?"Allowed: ":"Allow: ")+"Floating island",()->startActivity(new Intent(Settings.ACTION_MANAGE_OVERLAY_PERMISSION,Uri.parse("package:"+getPackageName()))),false);button(content,"Model / BYOK settings",()->showScreen("Settings"),false);content.addView(muted("Android requires you to grant these permissions in its own settings. Missing phone permissions do not block coding. Bots continue outside the app; Android battery restrictions still apply.",12));button(content,"Continue to bots",()->{getSharedPreferences("bot-setup",0).edit().putBoolean("seen-v2",true).apply();open("");},true);
    }
    @Override public void onRequestPermissionsResult(int request,String[] permissions,int[] results){super.onRequestPermissionsResult(request,permissions,results);if(screen.equals("Setup"))setup();}
    @Override public void onBackPressed(){if(drawer!=null){menu();return;}if(!screen.equals("Chat")){showScreen("Chat");return;}if(!selected.isEmpty())open("");else super.onBackPressed();}
    private void connections(){request("GET","/connectors",null,value -> {JSONArray list=(JSONArray)value;LinearLayout form=column();form.setPadding(dp(12),0,dp(12),dp(12));button(form,"Add MCP connection",() -> connectionForm(null),true);for(int i=0;i<list.length();i++){JSONObject c=list.optJSONObject(i);button(form,c.optString("name")+" · "+c.optString("transport"),() -> new AlertDialog.Builder(this).setTitle(c.optString("name")).setItems(new String[]{"Test connection","Edit","Remove"},(d,n) -> {if(n==0)request("POST","/connectors/"+c.optString("id")+"/test",json(),r -> new AlertDialog.Builder(this).setTitle("Connected").setMessage(((JSONObject)r).optJSONArray("tools").length()+" tools available").setPositiveButton("OK",null).show());if(n==1)connectionForm(c);if(n==2)request("DELETE","/connectors/"+c.optString("id"),null,r -> {refresh(false);});}).show(),false);}ScrollView scroll=new ScrollView(this);scroll.addView(form);new AlertDialog.Builder(this).setTitle("MCP connections").setView(scroll).setPositiveButton("Close",null).show();});}
    private void connectionForm(JSONObject previous){LinearLayout form=column();form.setPadding(dp(16),0,dp(16),dp(16));EditText name=field(form,"Name",previous==null?"":previous.optString("name"),false);Spinner transport=new Spinner(this);transport.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"HTTP endpoint","Local stdio command"}));form.addView(transport);if(previous!=null)transport.setSelection(previous.optString("transport").equals("stdio")?1:0);EditText url=field(form,"HTTP URL",previous==null?"":previous.optString("url"),false),token=field(form,"Bearer token · blank keeps saved token","",true),command=field(form,"Local executable",previous==null?"npx":previous.optString("command"),false),args=field(form,"Arguments · JSON array",previous==null?"[]":previous.optJSONArray("args").toString(),false);ScrollView scroll=new ScrollView(this);scroll.addView(form);AlertDialog dialog=new AlertDialog.Builder(this).setTitle("MCP connection").setView(scroll).setPositiveButton("Save",null).setNegativeButton("Cancel",null).create();dialog.setOnShowListener(v -> dialog.getButton(-1).setOnClickListener(w -> {try{JSONObject data=json("name",name.getText().toString(),"transport",transport.getSelectedItemPosition()==0?"http":"stdio","url",url.getText().toString(),"token",token.getText().toString(),"command",command.getText().toString(),"args",new JSONArray(args.getText().toString()));if(previous!=null)data.put("id",previous.optString("id"));request("POST","/connectors",data,r -> {dialog.dismiss();refresh(false);});}catch(Exception e){error(e);}}));dialog.show();}
}
